const fs = require('fs')
const path = require('path')
const root = __dirname
const req = require('module').createRequire(path.join(root, 'package.json'))
const { createBundleRenderer } = req('vue-server-renderer')
const { JSDOM, VirtualConsole } = require('/Users/didi/work/mpx/node_modules/jest-environment-jsdom/node_modules/jsdom')
const manifest = require('./dist/client/vue-ssr-client-manifest.json')
const renderer = createBundleRenderer(require('./dist/server/vue-ssr-server-bundle.json'), {
  runInNewContext: false,
  template: fs.readFileSync(path.join(root, 'public/index.html'), 'utf8'),
  clientManifest: manifest
})
async function render (id) {
  const context = { url: '/pages/article/index?id=' + id }
  const html = await renderer.renderToString(context)
  return { context, html }
}

test('concurrent SSR requests wait for their article and serialize isolated final state', async () => {
  const [a, b] = await Promise.all([render('a'), render('b')])
  expect(a.html).toContain('这是文章 A 的正文。')
  expect(b.html).toContain('这是文章 B 的正文。')
  expect(a.html).not.toContain('这是文章 B 的正文。')
  expect(b.html).not.toContain('这是文章 A 的正文。')
  expect(a.html).not.toContain('加载中')
  expect(a.html).toContain('window.__INITIAL_STATE__=')
  expect(a.context.state.article).toMatchObject({ loadedId: 'a', loading: false, errorText: '', article: { id: 'a' } })
  expect(b.context.state.article).toMatchObject({ loadedId: 'b', loading: false, errorText: '', article: { id: 'b' } })
  expect(a.context.state).not.toBe(b.context.state)
  expect(manifest.publicPath).toBe('/help-demo/')
  a.context.state.article.article.title = 'local mutation'
  expect(b.context.state.article.article.title).toBe('文章 B')
  expect((await render('a')).context.state.article.article.title).toBe('文章 A')
})

test('SSR failures produce the original settled error state without a success marker', async () => {
  const { context, html } = await render('missing')
  expect(html).toContain('文章不存在')
  expect(html).not.toContain('加载中')
  expect(context.state.article).toMatchObject({ article: null, loading: false, errorText: '文章不存在', loadedId: null })
})

test.each(['a', 'b'])('browser hydrates article %s without refetch and keeps expand interaction', async id => {
  const { html } = await render(id)
  const errors = []
  const virtualConsole = new VirtualConsole()
  virtualConsole.on('jsdomError', e => errors.push(e.message))
  virtualConsole.on('error', e => errors.push(String(e)))
  const dom = new JSDOM(html, { url: 'https://example.test/help-demo/pages/article/index?id=' + id, runScripts: 'dangerously', pretendToBeVisual: true, virtualConsole })
  try {
    const { window } = dom
    const title = window.document.querySelector('.title')
    const timers = []
    const originalSetTimeout = window.setTimeout.bind(window)
    window.setTimeout = (fn, delay, ...args) => {
      timers.push(delay)
      return originalSetTimeout(fn, delay, ...args)
    }
    manifest.initial.filter(file => file.endsWith('.js')).forEach(file => window.eval(fs.readFileSync(path.join(root, 'dist/client', file), 'utf8')))
    await new Promise(resolve => setTimeout(resolve, 80))
    expect(errors).toEqual([])
    expect(window.document.querySelector('.title')).toBe(title)
    expect(window.document.querySelector('.body').textContent).toBe('这是文章 ' + id.toUpperCase() + ' 的正文。')
    expect(timers.filter(delay => delay === 40 || delay === 10)).toEqual([])
    const button = window.document.querySelector('button')
    button.dispatchEvent(new window.MouseEvent('click', { bubbles: true }))
    await new Promise(resolve => setTimeout(resolve, 0))
    expect(window.document.querySelector('.article').textContent).toContain('文章 ' + id.toUpperCase() + ' 的补充说明。')
    expect(button.textContent).toContain('收起')
    button.dispatchEvent(new window.MouseEvent('click', { bubbles: true }))
    await new Promise(resolve => setTimeout(resolve, 0))
    expect(window.document.querySelector('.article').textContent).not.toContain('的补充说明。')
  } finally { dom.window.close() }
})
